code.source:
#include <iostream>
using namespace std;

int main() {
    int marks = 82;
    if (marks >= 90) {
        cout << "Grade A" << endl;
    } else if (marks >= 75) {
        cout << "Grade B" << endl;
    } else if (marks >= 50) {
        cout << "Grade C" << endl;
    } else {
        cout << "Grade D" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int age = 65;
    int price;
    if (age < 5) {
        price = 0;
    } else if (age < 18) {
        price = 50;
    } else if (age < 60) {
        price = 100;
    } else {
        price = 60;
    }
    cout << "Price: " << price << endl;
    return 0;
}

